import numpy as np
class PerKmModel:
    def fit(self, km, minutes):
        self.rate_ = float(np.sum(minutes) / np.sum(km))
        return self
    def predict(self, km):
        return np.asarray(km) * self.rate_
model = PerKmModel().fit([2, 3, 5], [16, 21, 43])
print(model.predict([4, 10]).tolist())
